using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using UnityEngine;

namespace SMMARTS
{
    /// <summary>
    /// Utility class for reading CSV data with consistent parsing and error handling.
    /// Handles session ID headers, column parsing, and data type conversion for replay system.
    /// Designed to work with CSV files generated by CSVWriter during recording.
    /// </summary>
    public class CSVReader
    {
        private string filePath;
        private string sessionID;
        private string[] columnHeaders;
        private List<Dictionary<string, string>> dataRows;
        private bool isLoaded = false;

        /// <summary>
        /// Initialize CSV reader with file path
        /// </summary>
        /// <param name="csvFilePath">Full path to CSV file</param>
        public CSVReader(string csvFilePath)
        {
            filePath = csvFilePath;
            dataRows = new List<Dictionary<string, string>>();
        }

        /// <summary>
        /// Load and parse the CSV file
        /// </summary>
        /// <returns>True if loaded successfully</returns>
        public bool LoadCSV()
        {
            if (!File.Exists(filePath))
            {
                Debug.LogError($"CSV file not found: {filePath}");
                return false;
            }

            try
            {
                string[] lines = File.ReadAllLines(filePath);

                if (lines.Length < 2)
                {
                    Debug.LogError($"CSV file too short: {filePath}");
                    return false;
                }

                // Parse session ID header (first line: SessionID,actual_session_id)
                if (lines[0].StartsWith("SessionID,"))
                {
                    sessionID = lines[0].Substring(10); // Remove "SessionID," prefix
                    // Debug.Log($"Loaded CSV session ID: {sessionID}");
                }
                else
                {
                    // Debug.LogWarning($"No session ID found in CSV: {filePath}");
                    sessionID = "Unknown";
                }

                // Parse column headers (second line)
                columnHeaders = ParseCSVLine(lines[1]);
                // Debug.Log($"CSV columns: {string.Join(", ", columnHeaders)}");

                // Parse data rows (remaining lines)
                dataRows.Clear();
                for (int i = 2; i < lines.Length; i++)
                {
                    if (string.IsNullOrWhiteSpace(lines[i])) continue; // Skip empty lines

                    string[] values = ParseCSVLine(lines[i]);

                    if (values.Length != columnHeaders.Length)
                    {
                        // Debug.LogWarning($"CSV row {i} has {values.Length} values but expected {columnHeaders.Length}");
                        continue;
                    }

                    // Create dictionary mapping column names to values
                    Dictionary<string, string> row = new Dictionary<string, string>();
                    for (int j = 0; j < columnHeaders.Length; j++)
                    {
                        row[columnHeaders[j]] = values[j];
                    }
                    dataRows.Add(row);
                }

                isLoaded = true;
                Debug.Log($"Successfully loaded CSV: {Path.GetFileName(filePath)} with {dataRows.Count} data rows");
                return true;
            }
            catch (Exception e)
            {
                Debug.LogError($"Error loading CSV {filePath}: {e.Message}");
                return false;
            }
        }

        /// <summary>
        /// Parse a single CSV line, handling commas within quotes
        /// </summary>
        private string[] ParseCSVLine(string line)
        {
            List<string> values = new List<string>();
            bool inQuotes = false;
            string currentValue = "";

            for (int i = 0; i < line.Length; i++)
            {
                char c = line[i];

                if (c == '"')
                {
                    // A doubled quote ("") inside a quoted field is an escaped literal quote
                    if (inQuotes && i + 1 < line.Length && line[i + 1] == '"')
                    {
                        currentValue += '"';
                        i++; // skip the second quote of the pair
                    }
                    else
                    {
                        inQuotes = !inQuotes;
                    }
                }
                else if (c == ',' && !inQuotes)
                {
                    values.Add(currentValue.Trim());
                    currentValue = "";
                }
                else
                {
                    currentValue += c;
                }
            }

            // Add the last value
            values.Add(currentValue.Trim());
            return values.ToArray();
        }

        /// <summary>
        /// Get all data rows
        /// </summary>
        public List<Dictionary<string, string>> GetAllRows()
        {
            return isLoaded ? dataRows : new List<Dictionary<string, string>>();
        }

        /// <summary>
        /// Get a specific column from all rows
        /// </summary>
        public List<string> GetColumn(string columnName)
        {
            List<string> columnData = new List<string>();

            if (!isLoaded) return columnData;

            foreach (var row in dataRows)
            {
                if (row.ContainsKey(columnName))
                {
                    columnData.Add(row[columnName]);
                }
                else
                {
                    columnData.Add(""); // Missing value
                }
            }

            return columnData;
        }

        /// <summary>
        /// Get a specific row by index
        /// </summary>
        public Dictionary<string, string> GetRow(int index)
        {
            if (!isLoaded || index < 0 || index >= dataRows.Count)
                return new Dictionary<string, string>();

            return dataRows[index];
        }

        /// <summary>
        /// Convert string value to float with error handling
        /// </summary>
        public static float ParseFloat(string value, float defaultValue = 0f)
        {
            if (float.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out float result))
                return result;

            Debug.LogWarning($"Failed to parse float: '{value}', using default: {defaultValue}");
            return defaultValue;
        }

        /// <summary>
        /// Convert string value to int with error handling
        /// </summary>
        public static int ParseInt(string value, int defaultValue = 0)
        {
            if (int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out int result))
                return result;

            Debug.LogWarning($"Failed to parse int: '{value}', using default: {defaultValue}");
            return defaultValue;
        }

        /// <summary>
        /// Convert string value to bool with error handling
        /// </summary>
        public static bool ParseBool(string value, bool defaultValue = false)
        {
            if (bool.TryParse(value, out bool result))
                return result;

            Debug.LogWarning($"Failed to parse bool: '{value}', using default: {defaultValue}");
            return defaultValue;
        }

        /// <summary>
        /// Public properties
        /// </summary>
        public string SessionID => sessionID;
        public string[] ColumnHeaders => columnHeaders;
        public int RowCount => isLoaded ? dataRows.Count : 0;
        public bool IsLoaded => isLoaded;
        public string FilePath => filePath;
    }
}